from concurrent.futures import ThreadPoolExecutor
field = list(range(1000))
def gather(lo, hi):
    if hi - lo <= 250: return sum(field[lo:hi])
    mid = (lo + hi)//2
    with ThreadPoolExecutor(2) as ex:
        f = ex.submit(gather, lo, mid)
        return f.result() + gather(mid, hi)
print("harvest total:", gather(0, len(field)))
assert gather(0, len(field)) == sum(field)

